from itertools import accumulate


def get_total_number_of_sequences(m, n):
    """Write a function to find the number of possible sequences of length n such that each of the next element is greater than or equal to twice of the previous element but less than or equal to m."""
    if m <= 0 or n <= 0:
        return 0
    if n == 1:
        return m
    if n > m.bit_length():
        # The shortest possible sequence is 1, 2, 4, ..., 2 ** (n - 1).
        return 0

    # Let F_k(x) be the number of valid sequences of length k whose
    # elements are all <= x.  Then F_1(x) = x and, by considering
    # whether the last element is < x or equal to x,
    # F_k(x) = F_k(x - 1) + F_{k - 1}(x // 2).  Hence F_k is the
    # prefix sum of F_{k - 1}(value // 2).  Computing F_k only up to
    # m // 2 ** (n - k) is sufficient, because larger values of that
    # row are never needed for the final answer.
    limit = m >> (n - 1)
    previous = list(range(limit + 1))
    for length in range(2, n + 1):
        limit = m >> (n - length)
        increments = [previous[value // 2] for value in range(limit + 1)]
        previous = list(accumulate(increments))
    return previous[-1]
